'use strict';
const KEY='willow-commons-demo-v1', money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10l9-7 9 7v10H3z M9 20v-8h6v8',payments:'M3 5h18v14H3z M3 9h18 M6 15h4',maintenance:'M14 3a6 6 0 0 0-7 7L3 17l4 4 7-7a6 6 0 0 0 7-7l-4 4-4-4z',calendar:'M4 5h16v16H4z M4 10h16 M8 3v4 M16 3v4',contacts:'M16 21v-3a4 4 0 0 0-8 0v3 M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M3 5v16 M21 5v16',arrow:'M5 12h14 M14 7l5 5-5 5',leaf:'M12 21V9 M12 15C3 15 3 6 3 4c7 0 9 5 9 8 M12 10c0-6 5-7 9-7 0 7-4 10-9 10',bell:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4z M10 21h4'};
const icon=k=>`<svg class="ico" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]||paths.home}"/></svg>`;
function seed(){return {community:'Willow Commons',paymentUrl:'',apartments:Array.from({length:100},(_,i)=>({id:i+1,number:String(101+i),block:String.fromCharCode(65+Math.floor(i/20)),name:i===0?'Alex Morgan':`Sample Resident ${i+1}`,rent:1450,water:38,insurance:15,trash:20,pest:5,additional:0})),autopay:{},requests:[{id:'WC-1042',apt:1,title:'Kitchen faucet dripping',category:'Plumbing',details:'Slow drip from the kitchen faucet.',priority:'Normal',entry:'Contact me first',status:'In progress',date:'2026-10-25T10:30'}],announcements:[{id:'a1',title:'A little care for our shared spaces',body:'Our landscaping team will refresh the courtyard beds this Thursday. Please keep the walkways clear between 9 AM and noon.',date:'2026-10-26'},{id:'a2',title:'A friendly reminder: November rent',body:'Your November statement is ready. Review your balance and pay through the community payment website.',date:'2026-10-25'}],events:[{id:'e1',title:'Coffee & neighbors',start:'2026-11-01T09:00',end:'2026-11-01T10:30',location:'Community lounge',body:'Start your Sunday with coffee and good company.'},{id:'e2',title:'Fall courtyard gathering',start:'2026-11-07T17:30',end:'2026-11-07T19:30',location:'Central courtyard',body:'An easy evening of cider, snacks, and conversation.'},{id:'e3',title:'Resident office hours',start:'2026-11-12T16:00',end:'2026-11-12T18:00',location:'Leasing office',body:'Stop by with questions for the community team.'}],contacts:[{id:'c1',name:'Jamie Ellis',role:'Community manager',availability:'Monday–Friday · 9 AM–5 PM',contact:'manager@example.invalid',kind:'Office'},{id:'c2',name:'Taylor Reed',role:'Resident services',availability:'Monday–Friday · 9 AM–5 PM',contact:'residents@example.invalid',kind:'Office'},{id:'c3',name:'Maintenance team',role:'Emergency / after-hours maintenance',availability:'24 hours · urgent property issues',contact:'Phone number not configured — sample only',kind:'Emergency'}]};}
let state;try{state=JSON.parse(localStorage.getItem(KEY))||seed()}catch{state=seed()}
let page='home',role='resident',aptId=1,adminTab='apartments',month=10,year=2026,installPrompt;
const apt=()=>state.apartments.find(a=>a.id===aptId), charges=a=>[['Rent',a.rent],['Water',a.water],["Renters insurance",a.insurance],['Trash',a.trash],['Pest control',a.pest],['Additional charges',a.additional]],total=a=>charges(a).reduce((s,c)=>s+Number(c[1]),0);
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('Browser storage is unavailable. Changes last only in this session.');return false}}
function toast(s){let t=document.querySelector('#toast');t.textContent=s;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',4500)}
const date=s=>new Date(s.length===10?s+'T12:00':s).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
const time=s=>new Date(s).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'});
const navItems=[['home','Overview'],['payments','Payments'],['maintenance','Maintenance'],['calendar','Community'],['contacts','Contact office']];
function render(){document.querySelector('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brandmark">${icon('leaf')}</div><div>Goo Resident<br><small>YOUR COMMUNITY, CONNECTED</small></div></div><nav aria-label="Main navigation">${navItems.map(([id,label])=>`<button data-page="${id}" class="${page===id&&role==='resident'?'active':''}" ${page===id&&role==='resident'?'aria-current="page"':''}>${icon(id)}${label}</button>`).join('')}</nav><div class="sidebottom"><div class="side-note">${icon('leaf')}<h3>Your home, connected.</h3><p>Keep your community close, wherever your day takes you.</p><button class="small-btn" data-action="install">Install Goo Resident ↗</button></div><div class="person"><div class="avatar">${esc(apt().name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</div><div><b style="font-size:12px">${esc(apt().name)}</b><br><small>Apartment ${esc(apt().number)}</small></div></div></div></aside><main class="main"><header class="topbar"><span>Resident portal <span class="muted"> / ${role==='office'?'Office dashboard':navItems.find(n=>n[0]===page)[1]}</span></span><div class="mobilebrand">Goo Resident</div><div class="topright"><span class="tag">Sample community</span><button class="text-btn" data-action="role">${role==='resident'?'Demo office view':'Back to resident'}</button></div></header><div class="content">${role==='office'?admin():resident()}<div class="demo-strip"><b>Interactive demo.</b> Fictional residents and records. Changes save only in this browser. Role switching is a preview, not secure sign-in. No money is collected.</div><footer class="footer"><span>© 2026 Goo Resident · Your home, connected.</span><button class="small-btn" data-action="install">Website + installable app ↗</button></footer></div></main></div>`;bind();}
function resident(){return page==='home'?home():page==='payments'?payments():page==='maintenance'?maintenance():page==='calendar'?calendar():contacts()}
const head=(title,sub,button='')=>`<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div>${button}</div>`;
function bill(){return charges(apt()).map(([k,v])=>`<div class="bill-line"><span>${k}</span><span>${money(v)}</span></div>`).join('')}
function home(){return `<section class="welcome"><div><div class="eyebrow" style="margin-bottom:9px">Welcome home</div><h1>${esc(apt().name)}</h1><p>${esc(state.community)}</p></div><div class="apt">${icon('home')}Apartment ${esc(apt().number)}</div></section><div class="grid"><div class="stack"><section class="card balance"><div class="eyebrow">Total outstanding</div><div class="amount">${money(total(apt()))}</div><small>November 2026 statement · Due November 1</small><div class="balance-actions"><button class="btn primary" data-action="pay">Make a Payment ${icon('arrow')}</button><button class="btn secondary" data-action="autopay">Auto-pay ${icon('calendar')}</button></div><div style="margin-top:15px"><small>${state.autopay[aptId]?.items.length?'Monthly preferences saved · demo only':'Auto-pay is not active · Set your preferences'}</small></div></section><section class="card"><div class="card-head"><h2>Your monthly charges</h2><span class="tag">Nov 2026</span></div>${bill()}<div class="bill-line total"><span>Total outstanding</span><span>${money(total(apt()))}</span></div><button class="text-btn" data-page="payments" style="padding:15px 0 0">View 12-month payment history →</button></section><section class="card"><div class="card-head"><h2>Community board</h2>${icon('bell')}</div>${announcements()}</section></div><div class="stack"><section class="card maintenance"><div class="row"><div class="service-icon">${icon('maintenance')}</div><div><h2>A little help at home?</h2><p>Our maintenance team is here for you.</p></div></div><button class="btn" data-page="maintenance" style="width:100%">Maintenance requests ${icon('arrow')}</button><p style="margin-bottom:0;font-size:11px">${state.requests.filter(r=>r.apt===aptId&&r.status!=='Completed').length} open request(s) · View history or create a request</p></section><section class="card"><div class="community-art" aria-hidden="true"><svg viewBox="0 0 400 125" preserveAspectRatio="xMidYMid slice"><rect width="400" height="125" fill="#dce4ce"/><circle cx="305" cy="26" r="24" fill="#f7f4d8"/><path d="M0 100Q100 55 210 100T400 85V125H0" fill="#b7c9a0"/><path d="M60 112V45l48-25 48 25v67M171 112V60l48-25 48 25v52" fill="#f4f1df" stroke="#819778" stroke-width="2"/><path d="M60 45h96M171 60h96" stroke="#819778" stroke-width="2"/><g fill="#7a9274"><path d="M79 55h14v20H79zM121 55h14v20h-14zM100 88h16v24h-16zM189 71h14v17h-14zM231 71h14v17h-14zM211 94h15v18h-15z"/><ellipse cx="324" cy="79" rx="25" ry="35"/></g><path d="M324 85v40M35 88v37" stroke="#617b5c" stroke-width="3"/><ellipse cx="35" cy="74" rx="19" ry="28" fill="#879f75"/></svg></div><div class="card-head"><h2>Coming together</h2><button class="text-btn" data-page="calendar">Calendar →</button></div>${eventsList(state.events.slice().sort((a,b)=>a.start.localeCompare(b.start)).slice(0,2))}</section><section class="card"><div class="eyebrow">We're here for you</div><h3 style="margin:10px 0 7px">A familiar face. A helping hand.</h3><p class="muted" style="font-size:12px;margin-bottom:15px">Find office hours, your community team, and after-hours support.</p><button class="small-btn" data-page="contacts">Contact your community team →</button></section></div></div>`}
function announcements(){return state.announcements.map(a=>`<article class="notice"><small>COMMUNITY UPDATE · ${date(a.date)}</small><h3 style="margin-top:8px">${esc(a.title)}</h3><p>${esc(a.body)}</p></article>`).join('')||'<p class="empty">No announcements yet.</p>'}
function eventsList(items){return items.map(e=>`<article class="event"><div class="datebox"><small>${new Date(e.start).toLocaleDateString('en-US',{month:'short'}).toUpperCase()}</small><strong>${new Date(e.start).getDate()}</strong></div><div><h3>${esc(e.title)}</h3><p>${date(e.start)} · ${time(e.start)}–${date(e.end)!==date(e.start)?date(e.end)+' ':''}${time(e.end)} CT<br>${esc(e.location)}</p><p>${esc(e.body)}</p></div></article>`).join('')||'<p class="empty">No events this month.</p>'}
function payments(){return head('Payments','Your apartment statement and the last 12 months of sample payments.')+`<div class="grid"><section class="card"><div class="card-head"><h2>November statement</h2><span class="tag">Due Nov 1, 2026</span></div>${bill()}<div class="bill-line total"><span>Total outstanding</span><span>${money(total(apt()))}</span></div><div class="balance-actions"><button class="btn primary" data-action="pay">Make a Payment</button><button class="btn" data-action="autopay">Auto-pay</button></div></section><section class="card"><h2>Monthly, on your terms</h2><p class="muted" style="margin:15px 0">Choose eligible charges and one monthly payment date: the 1st, 2nd, or 3rd.</p><div class="hint">${state.autopay[aptId]?.items.length?`Saved preferences: ${state.autopay[aptId].items.map(esc).join(', ')}. Once each month on day ${state.autopay[aptId].day}.`:'No auto-pay preferences selected.'}<br><b>Demo only:</b> saving preferences does not authorize or schedule a real payment.</div><button class="btn" data-action="autopay">Manage preferences</button></section><section class="card full"><div class="card-head"><h2>Payment history</h2><span class="tag">Nov 2025–Oct 2026</span></div><p class="muted" style="font-size:12px;margin-bottom:15px">12 sample monthly records for apartment ${esc(apt().number)}. These are not receipts.</p><div class="table-wrap"><table><thead><tr><th>Payment date</th><th>Reference</th><th>Status</th><th style="text-align:right">Amount</th></tr></thead><tbody>${Array.from({length:12},(_,i)=>{const d=new Date(2026,9-i,1);return `<tr><td>${date(d.toISOString())}</td><td>DEMO-${aptId}-${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}</td><td><span class="badge good">Sample paid</span></td><td>${money(1528)}</td></tr>`}).join('')}</tbody></table></div></section></div>`}
function maintenance(){const list=state.requests.filter(r=>r.apt===aptId);return head('Maintenance','A comfortable home starts with things that work.',`<button class="btn primary" data-action="request">+ New request</button>`)+`<div class="hint">For an urgent property issue, use the <button class="text-btn" data-page="contacts">emergency / after-hours contact directory</button>. Demo requests are not sent to staff.</div><section class="card"><div class="card-head"><h2>Request history</h2><span class="tag">${list.length} request(s)</span></div>${list.map(r=>`<article class="notice"><div class="card-head" style="margin-bottom:10px"><h3>${esc(r.title)}</h3><span class="badge ${r.status==='Completed'?'good':''}">${esc(r.status)}</span></div><p>${esc(r.details)}</p><small>${esc(r.id)} · ${date(r.date)} · ${esc(r.category)} · ${esc(r.priority)} priority</small><p style="font-size:11px">Entry preference: ${esc(r.entry)}</p></article>`).join('')||'<p class="empty">No requests yet. Create one whenever you need a hand.</p>'}</section>`}
function calendar(){const ev=state.events.filter(e=>new Date(e.start).getMonth()===month&&new Date(e.start).getFullYear()===year).sort((a,b)=>a.start.localeCompare(b.start));const offset=new Date(year,month,1).getDay(),days=new Date(year,month+1,0).getDate();return head('Around the community','Good things happen close to home. All event times are Central Time.')+`<div class="grid"><section class="card"><div class="card-head"><h2>${new Date(year,month,1).toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h2><div><button class="btn" data-action="prev-month" aria-label="Previous month">‹</button> <button class="btn" data-action="next-month" aria-label="Next month">›</button></div></div><div class="calendar">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="day-title">${d}</div>`).join('')}${'<div></div>'.repeat(offset)}${Array.from({length:days},(_,i)=>{let items=ev.filter(e=>new Date(e.start).getDate()===i+1);return `<div class="day ${items.length?'has':''}">${i+1}${items.map(e=>`<span>${esc(e.title)}</span>`).join('')}</div>`}).join('')}</div></section><section class="card"><h2>This month's events</h2>${eventsList(ev)}</section><section class="card full"><h2>Community announcements</h2>${announcements()}</section></div>`}
function contacts(){return head('Your community team','People to turn to, from everyday questions to after-hours help.')+`<div class="hint">All contacts below are samples. Email addresses use a non-deliverable domain and no real phone numbers are configured. For immediate danger, contact your local emergency services.</div><section class="card">${state.contacts.map(c=>`<article class="contact"><div class="row"><div class="service-icon">${icon('contacts')}</div><div><span class="eyebrow">${esc(c.kind)}</span><h2 style="margin:5px 0">${esc(c.role)}</h2><p>${esc(c.name)}</p><p class="muted">${esc(c.availability)}</p><p>${esc(c.contact)}</p></div></div></article>`).join('')}</section>`}
function modal(title,body){const m=document.querySelector('#modal');m.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" aria-label="Close dialog" data-action="close">×</button></div>${body}`;m.showModal();bind(m)}
function pay(){modal('Make a Payment',`<p style="margin-bottom:18px">Your outstanding balance is <b>${money(total(apt()))}</b>.</p><div class="hint">Payments are completed on the community's external payment website. Card information is never entered here. This portal cannot confirm payment status.</div>${state.paymentUrl?`<p>Configured destination:</p><p style="overflow-wrap:anywhere;margin:10px 0 20px">${esc(state.paymentUrl)}</p><a class="btn primary" href="${esc(state.paymentUrl)}" target="_blank" rel="noopener noreferrer">Continue to payment website ↗</a>`:'<p><b>Payment website not configured.</b></p><p class="muted" style="margin-top:8px">The office can add the community’s HTTPS payment URL in Settings. No payment will be collected in this demo.</p>'}`)}
function autopay(){let pref=state.autopay[aptId]||{items:[],day:'1'};modal('Auto-pay preferences',`<p class="muted" style="font-size:13px;margin-bottom:18px">Choose charges to pay once per month. Each selected charge is paid once, on your chosen day.</p><form id="auto-form">${['Rent','Trash','Water / utilities','Pest control'].map(v=>`<label class="check"><input type="checkbox" name="items" value="${v}" ${pref.items.includes(v)?'checked':''}>${v}</label>`).join('')}<label>Monthly payment date<select name="day">${[1,2,3].map(d=>`<option value="${d}" ${+pref.day===d?'selected':''}>${d}${d===1?'st':d===2?'nd':'rd'} of every month</option>`).join('')}</select></label><div class="hint">Electricity is excluded. Renters insurance and additional charges are not eligible here. Preferences are saved locally; a payment provider, authorization, and a backend are required to activate recurring payments.</div><button class="btn primary" type="submit">Save demo preferences</button></form>`);document.querySelector('#auto-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.autopay[aptId]={items:f.getAll('items'),day:f.get('day')};save();close();render();toast('Preferences saved. No real auto-pay is scheduled.')}}
const input=(label,name,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra} required></label>`;
const select=(label,name,values,value)=>`<label>${label}<select name="${name}">${values.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
function request(){modal('New maintenance request',`<form id="request-form">${input('Short description','title','','text','maxlength="100"')}${select('Category','category',['Plumbing','Heating / cooling','Appliance','Electrical repair','Other'])}<label>Tell us what is happening<textarea name="details" required maxlength="2000"></textarea></label><div class="form-grid">${select('Priority','priority',['Normal','Urgent'])}${select('Entry preference','entry',['Contact me first','Permission to enter'])}</div><div class="hint">For emergencies, use the staff contact directory. This demo saves your request locally and does not dispatch staff.</div><button type="submit" class="btn primary">Submit demo request</button></form>`);document.querySelector('#request-form').onsubmit=e=>{e.preventDefault();let r=Object.fromEntries(new FormData(e.target));state.requests.unshift({...r,id:'WC-'+Date.now().toString().slice(-7),apt:aptId,status:'Submitted',date:new Date().toISOString()});save();close();render();toast('Demo request saved to your history.')}}
function close(){document.querySelector('#modal').close()}
function admin(){const tabs=['apartments','maintenance','events','announcements','contacts','settings'];return head('Community office','Manage Willow Commons · 5 blocks · 20 apartments per block.')+`<div class="hint"><b>Demo administration:</b> everyone with this preview can switch roles. This is not authentication or secure resident isolation. Never enter real resident or financial information.</div><div class="stats"><div class="card"><small>Apartments</small><strong>100</strong></div><div class="card"><small>Blocks</small><strong>5</strong></div><div class="card"><small>Open requests</small><strong>${state.requests.filter(r=>r.status!=='Completed').length}</strong></div></div><div class="admin-tabs">${tabs.map(t=>`<button class="btn ${t===adminTab?'active':''}" data-tab="${t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div>${adminContent()}`}
function adminContent(){if(adminTab==='apartments')return `<section class="card"><div class="card-head"><h2>Apartment directory & charges</h2><span class="tag">100 apartments</span></div><label>Filter apartments<input id="apt-search" placeholder="Resident, apartment, or block"></label><div class="table-wrap"><table><thead><tr><th>Apartment</th><th>Block</th><th>Primary leaseholder</th><th>Outstanding</th><th>Actions</th></tr></thead><tbody>${state.apartments.map(a=>`<tr data-search="${esc((a.number+' '+a.block+' '+a.name).toLowerCase())}"><td>${esc(a.number)}</td><td>${a.block}</td><td>${esc(a.name)}</td><td>${money(total(a))}</td><td><button class="text-btn" data-edit-apt="${a.id}">Edit</button><button class="text-btn" data-preview="${a.id}">Preview resident</button></td></tr>`).join('')}</tbody></table></div></section>`;
if(adminTab==='maintenance')return `<section class="card"><h2>All maintenance requests</h2>${state.requests.map(r=>`<article class="notice"><h3>${esc(r.title)}</h3><p>Apartment ${esc(state.apartments.find(a=>a.id===r.apt).number)} · ${esc(r.id)} · ${esc(r.priority)}</p><p>${esc(r.details)}</p><small>Entry: ${esc(r.entry)} · ${date(r.date)}</small><label style="margin-top:12px">Status<select data-status="${r.id}">${['Submitted','In progress','Completed'].map(v=>`<option ${v===r.status?'selected':''}>${v}</option>`).join('')}</select></label></article>`).join('')||'<p class="empty">No maintenance requests.</p>'}</section>`;
if(adminTab==='settings')return `<section class="card"><h2>Community settings</h2><form id="settings-form" style="margin-top:20px">${input('Community name','community',state.community,'text','maxlength="80"')}<label>External payment website (HTTPS)<input name="paymentUrl" type="url" value="${esc(state.paymentUrl)}" placeholder="https://your-provider.example/community"></label><div class="hint">Leave blank until a real provider URL is available. Residents will review this destination before opening it. This setting does not connect payment status or enable auto-pay.</div><button class="btn primary" type="submit">Save settings</button></form></section>`;
const t=adminTab;return `<section class="card"><div class="card-head"><h2>${t[0].toUpperCase()+t.slice(1)}</h2><button class="btn primary" data-new="${t}">+ Add ${t==='announcements'?'announcement':t==='contacts'?'contact':'event'}</button></div>${state[t].map(x=>`<article class="notice"><div class="card-head" style="margin-bottom:8px"><h3>${esc(x.title||x.role)}</h3><div><button class="text-btn" data-edit="${x.id}" data-kind="${t}">Edit</button><button class="text-btn delete" data-delete="${x.id}" data-kind="${t}">Delete</button></div></div><p>${esc(x.body||x.name)}</p><small>${t==='events'?`${date(x.start)} ${time(x.start)} – ${date(x.end)} ${time(x.end)} CT · ${esc(x.location)}`:t==='contacts'?`${esc(x.availability)} · ${esc(x.contact)}`:date(x.date)}</small></article>`).join('')||'<p class="empty">Nothing posted yet.</p>'}</section>`}
function editApartment(id){const a=state.apartments.find(x=>x.id===id);modal(`Apartment ${esc(a.number)} · Block ${a.block}`,`<form id="apt-form">${input('Primary leaseholder','name',a.name,'text','maxlength="80"')}<div class="form-grid">${[['rent','Rent'],['water','Water'],['insurance','Renters insurance'],['trash','Trash'],['pest','Pest control'],['additional','Additional charges']].map(([k,l])=>input(l+' ($)',k,a[k],'number','min="0" max="100000" step="0.01"')).join('')}</div><p class="hint">Office-controlled November 2026 statement. Electricity is excluded.</p><button class="btn primary" type="submit">Save apartment & charges</button></form>`);document.querySelector('#apt-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));Object.keys(f).forEach(k=>a[k]=k==='name'?f[k]:Number(f[k]));save();close();render();toast('Apartment and charges updated.')}}
function editRecord(kind,id){const x=state[kind].find(x=>x.id===id)||{};let fields=kind==='contacts'?input('Name or team','name',x.name)+input('Role','role',x.role)+input('Availability','availability',x.availability)+input('Contact details','contact',x.contact)+select('Contact type','kind',['Office','Emergency'],x.kind):input('Title','title',x.title)+`<label>Description<textarea name="body" required maxlength="2000">${esc(x.body)}</textarea></label>`+(kind==='events'?input('Start (Central Time)','start',x.start||'2026-11-01T09:00','datetime-local')+input('End (Central Time)','end',x.end||'2026-11-01T10:00','datetime-local')+input('Location','location',x.location):input('Posted date','date',x.date||'2026-10-27','date'));modal(`${id?'Edit':'Add'} ${kind==='contacts'?'contact':kind==='events'?'event':'announcement'}`,`<form id="record-form">${fields}<button class="btn primary" type="submit">Save ${kind==='contacts'?'contact':'post'}</button></form>`);document.querySelector('#record-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(kind==='events'&&f.end<=f.start){toast('End must be after the start.');return}if(id)Object.assign(x,f);else state[kind].unshift({...f,id:kind[0]+Date.now()});save();close();render();toast('Saved to this demo community.')}}
function bind(root=document){root.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;role='resident';render();window.scrollTo(0,0)});root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{adminTab=b.dataset.tab;render()});root.querySelectorAll('[data-edit-apt]').forEach(b=>b.onclick=()=>editApartment(+b.dataset.editApt));root.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{aptId=+b.dataset.preview;role='resident';page='home';render();window.scrollTo(0,0)});root.querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>editRecord(b.dataset.new));root.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editRecord(b.dataset.kind,b.dataset.edit));root.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{modal('Delete this item?',`<p>This removes the item from the demo community.</p><div class="actions"><button class="btn" data-action="close">Cancel</button><button class="btn primary" id="confirm-delete">Delete item</button></div>`);document.querySelector('#confirm-delete').onclick=()=>{state[b.dataset.kind]=state[b.dataset.kind].filter(x=>x.id!==b.dataset.delete);save();close();render();toast('Item deleted.')}});root.querySelectorAll('[data-status]').forEach(b=>b.onchange=()=>{state.requests.find(r=>r.id===b.dataset.status).status=b.value;save();toast('Maintenance status updated.')});let search=root.querySelector('#apt-search');if(search)search.oninput=()=>root.querySelectorAll('[data-search]').forEach(r=>r.hidden=!r.dataset.search.includes(search.value.toLowerCase()));let form=root.querySelector('#settings-form');if(form)form.onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(form));if(f.paymentUrl){try{const url=new URL(f.paymentUrl);if(url.protocol!=='https:'||url.username||url.password)throw Error()}catch{toast('Enter an HTTPS URL without credentials.');return}}state.community=f.community;state.paymentUrl=f.paymentUrl;save();render();toast('Community settings saved.')}}
function action(a){if(a==='close')close();if(a==='pay')pay();if(a==='autopay')autopay();if(a==='request')request();if(a==='role'){role=role==='resident'?'office':'resident';render();window.scrollTo(0,0)}if(a==='prev-month'||a==='next-month'){month+=a==='prev-month'?-1:1;if(month<0){month=11;year--}if(month>11){month=0;year++}render()}if(a==='install'){if(installPrompt){installPrompt.prompt();installPrompt=null}else modal('Take Goo Resident with you',`<p>Install this website as an app from your browser.</p><div class="hint" style="margin-top:16px"><b>iPhone / iPad:</b> Open in Safari, tap Share, then Add to Home Screen.<br><b>Android:</b> Open in Chrome and choose Install app or Add to Home screen.<br><b>Desktop:</b> Use Chrome or Edge’s install icon in the address bar.</div><p class="muted">Installation availability depends on the browser and hosting access. This is a progressive web app, not an app-store native app. After an online visit, the local demo can work offline.</p>`)}}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});


